db:insert.db:input-parameters:
#[output application/java --- do {
	var d = vars.newRequest.detail default {}
	---
	{
		id: vars.requestId, idempotencyKey: vars.idempotencyKey, orderId: vars.newRequest.orderId, customerId: vars.customerId,
		requestType: vars.newRequest.'type', itemId: d.itemId, provider: d.provider, qty: d.quantity, unitPrice: d.price,
		amount: if (d.quantity != null and d.price != null) d.quantity * d.price else null,
		currency: d.currency default p('currency'), requestedBy: vars.actor
	}
}]

amqp:message.amqp:body:
#[output application/json --- do {
	var d = vars.newRequest.detail default {}
	---
	{
		eventType: "approval.requested", requestId: vars.requestId, orderId: vars.newRequest.orderId, customerId: vars.customerId,
		"type": vars.newRequest."type",
		amount: if (d.quantity != null and d.price != null) d.quantity * d.price else 0,
		currency: d.currency default p('currency'), requestedBy: vars.actor,
		expiresAt: ((now() + ("PT" ++ p('requests.expiryHours') ++ "H") as Period) >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"},
		occurredAt: (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
	}
}]

ee:variables.ee:set-variable:
%dw 2.0
output application/java
var q = attributes.queryParams default {}
var size = (q.size default p('requests.pageSize')) as Number
---
{ status: q.status, pageOffset: (((q.page default 1) as Number) - 1) * size, pageSize: size }
